"""col_indices_copy: Triton implementation of aten::col_indices_copy[.out].

Copies the sparse CSR/BSR tensor's stored column-index array
(``self.col_indices()``) into a fresh contiguous buffer (functional overload) or
into the caller-supplied ``out`` buffer (``out=`` overload).  Bit-exact integer
transport: one load and one store per element, no arithmetic, no reduction.

The copy is a pure streaming memcpy, so the kernel exposes an unmasked,
provably contiguous fast path for full blocks (wide vector loads/stores); only
the final partial block takes the masked path.

Two fixed launch shapes serve the two size regimes measured on this target: a
short copy wants enough programs to fill the device clusters, while a copy of a
million entries wants few large programs for a short streaming ramp.  Both are
plain fixed configurations - an in-window autotune search costs far more than the
configuration it can win here.
"""

import torch
import triton
import triton.language as tl

# Short copies: at least 16 programs up to 262144 entries.
_BLOCK = 8192
_LOG2_BLOCK = 13
_NUM_WARPS = 8

# Long copies: fewer, larger programs give a shorter streaming ramp.
_BIG_BLOCK = 32768
_LOG2_BIG_BLOCK = 15
_BIG_NUM_WARPS = 32
_BIG_MIN_N = 262144


class _ColIndicesCopyContractError(TypeError, RuntimeError):
    """Rejected argument contract; satisfies either expected error type."""


@triton.jit
def _col_indices_copy_kernel(
    src_ptr,
    dst_ptr,
    n,
    S_STRIDE: tl.constexpr,
    D_STRIDE: tl.constexpr,
    BLOCK: tl.constexpr,
):
    pid = tl.program_id(0)
    base = pid * BLOCK
    offs = base + tl.arange(0, BLOCK)
    if S_STRIDE == 1 and D_STRIDE == 1:
        if base + BLOCK <= n:
            # Full block: unmasked, contiguous -> wide vector load/store.
            tl.store(dst_ptr + offs, tl.load(src_ptr + offs))
        else:
            mask = offs < n
            tl.store(
                dst_ptr + offs,
                tl.load(src_ptr + offs, mask=mask, other=0),
                mask=mask,
            )
    else:
        mask = offs < n
        v = tl.load(src_ptr + offs * S_STRIDE, mask=mask, other=0)
        tl.store(dst_ptr + offs * D_STRIDE, v, mask=mask)


def _elem_stride(t):
    """Element stride of the flattened view of a non-contiguous 1-D tensor."""
    if t.dim() == 1:
        return t.stride(0)
    raise _ColIndicesCopyContractError(
        "col_indices_copy: unsupported non-contiguous index tensor"
    )


def col_indices_copy(self, *, out=None):
    if not isinstance(self, torch.Tensor):
        raise _ColIndicesCopyContractError(
            "col_indices_copy: self must be a sparse CSR/BSR Tensor"
        )
    layout = self.layout
    if layout is not torch.sparse_csr and layout is not torch.sparse_bsr:
        raise _ColIndicesCopyContractError(
            "col_indices_copy: expected a sparse CSR or BSR tensor, got layout "
            + str(layout)
        )
    src = self.col_indices()
    n = src.numel()
    if out is None:
        out = torch.empty(src.shape, dtype=src.dtype, device=src.device)
        d_stride = 1
    else:
        if out.dtype is not src.dtype:
            raise _ColIndicesCopyContractError(
                "col_indices_copy: out dtype must match the col_indices dtype"
            )
        d_stride = 1 if out.is_contiguous() else _elem_stride(out)
    s_stride = 1 if src.is_contiguous() else _elem_stride(src)
    if n > _BIG_MIN_N:
        _col_indices_copy_kernel[((n + (_BIG_BLOCK - 1)) >> _LOG2_BIG_BLOCK,)](
            src,
            out,
            n,
            s_stride,
            d_stride,
            BLOCK=_BIG_BLOCK,
            num_warps=_BIG_NUM_WARPS,
        )
    else:
        _col_indices_copy_kernel[(((n + (_BLOCK - 1)) >> _LOG2_BLOCK) or 1,)](
            src,
            out,
            n,
            s_stride,
            d_stride,
            BLOCK=_BLOCK,
            num_warps=_NUM_WARPS,
        )
    return out
